-- Each hospital's claim form: the fields printed on the filled-in form, as JSON
-- ({title, intro?, fields: [{key, label, text?}]}). The default is an NSW-style
-- study leave reimbursement form; src/claims/form.ts holds the same template
-- (DEFAULT_CLAIM_FORM) and a test keeps the two in step.
ALTER TABLE orgs ADD COLUMN claim_form_json TEXT NOT NULL DEFAULT '{"title":"Study Leave Reimbursement Claim","intro":"Claim for reimbursement of approved study leave (conference) expenses. Original receipts are attached.","fields":[{"key":"employee_name","label":"Employee name"},{"key":"employee_email","label":"Email"},{"key":"organisation","label":"Hospital / organisation"},{"key":"conference","label":"Conference / course"},{"key":"dates","label":"Dates of leave"},{"key":"location","label":"Location"},{"key":"expenses","label":"Itemised expenses"},{"key":"total","label":"Total claimed"},{"key":"declaration","label":"Declaration","text":"I declare that the expenses claimed were incurred by me while attending the approved study leave above, that the attached receipts are true copies, and that I have not claimed these expenses from any other source."},{"key":"date","label":"Date"}]}';
